    bc_reveal: 'ರಹಸ್ಯ ಸಂಖ್ಯೆಗಳು: {a} ಅವರದು {s1}, {b} ಅವರದು {s2}.', bc_played: 'ಆಟಗಳು', bc_best: 'ಕನಿಷ್ಠ ಊಹೆಗಳು', bc_now: 'ಈವರೆಗಿನ ಊಹೆಗಳು',
    help_title: 'ಹೇಗೆ ಆಡುವುದು / ಕುಟುಂಬ ಮತ್ತು ತರಗತಿಗೆ ಸಲಹೆಗಳು',
    help_ttt: 'ಟಿಕ್-ಟ್ಯಾಕ್-ಟೋ (ಗುಣಾಕಾರ-ಸೊನ್ನೆ): ಸರದಿಯಂತೆ ನಿಮ್ಮ X ಅಥವಾ O ಇಡಿ. 3 × 3 ರಲ್ಲಿ ಸಾಲಿನಲ್ಲಿ ಮೂರು ಆದರೆ ಗೆಲುವು; 4 × 4 ಮತ್ತು 5 × 5 ರಲ್ಲಿ ಸಾಲಿನಲ್ಲಿ ನಾಲ್ಕು ಬೇಕು. ಯಾರೂ ಸಾಲು ಮಾಡಲಾಗದಿದ್ದಾಗ ಸಮಬಲ.',
    help_c4: 'ನಾಲ್ಕರ ಸಾಲು: ಒಂದು ಕಾಲಂ ಒತ್ತಿ (ಅಥವಾ 1–7 ಒತ್ತಿ); ಕಾಯಿ ಕೆಳಗಿನ ಖಾಲಿ ಜಾಗಕ್ಕೆ ಬೀಳುತ್ತದೆ. ಅಡ್ಡ, ಉದ್ದ ಅಥವಾ ಓರೆಯಾಗಿ ನಾಲ್ಕರ ಸಾಲು ಮಾಡಿ. ನಡುವಿನ ಕಾಲಂನಿಂದ ಶುರು ಮಾಡುವುದು ಅತ್ಯಂತ ಬಲಶಾಲಿ.',
    help_dots: 'ಚುಕ್ಕೆ ಮತ್ತು ಪೆಟ್ಟಿಗೆ: ಪಕ್ಕದ ಎರಡು ಚುಕ್ಕೆ ಸೇರಿಸಿ. ನಿಮ್ಮ ಗೆರೆ ಪೆಟ್ಟಿಗೆಯ ನಾಲ್ಕನೇ ಬದಿ ಮುಚ್ಚಿದರೆ ಪೆಟ್ಟಿಗೆ ನಿಮ್ಮದು, ಮತ್ತೆ ನಿಮ್ಮ ಸರದಿ. ಸಲಹೆ: ಪೆಟ್ಟಿಗೆಯ ಮೂರನೇ ಬದಿ ಎಳೆಯಬೇಡಿ, ಇಲ್ಲದಿದ್ದರೆ ಎದುರಾಳಿ ಅದನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತಾರೆ.',
    help_bulls: 'ಎತ್ತು ಮತ್ತು ಹಸು: ರಹಸ್ಯ ಸಂಖ್ಯೆ ಊಹಿಸಿ. ಉದಾಹರಣೆ: ರಹಸ್ಯ 4271, ಊಹೆ 1234 → 1 ಎತ್ತು (2 ಸರಿಯಾದ ಜಾಗದಲ್ಲಿ), 2 ಹಸು (1 ಮತ್ತು 4). ಸುಳಿವುಗಳಿಂದ ಸಂಖ್ಯೆಗಳನ್ನು ತೆಗೆದುಹಾಕುತ್ತಾ ಹೋಗಿ.',
    help_ai: 'ಕಂಪ್ಯೂಟರ್ ಹೇಗೆ ಯೋಚಿಸುತ್ತದೆ: ಕಠಿಣ ಮಟ್ಟದಲ್ಲಿ ಅದು ಪ್ರತಿ ನಡೆ ಮತ್ತು ಅದರ ಪ್ರತಿ ಉತ್ತರವನ್ನು ಕಲ್ಪಿಸುತ್ತದೆ (ಇದನ್ನು ಮಿನಿಮ್ಯಾಕ್ಸ್ ಎನ್ನುತ್ತಾರೆ), ನೀವು ಅತ್ಯುತ್ತಮ ನಡೆ ಆಡುತ್ತೀರಿ ಎಂದು ಭಾವಿಸುತ್ತದೆ. 3 × 3 ರಲ್ಲಿ ಪ್ರತಿ ಆಟದ ಕೊನೆಯನ್ನೂ ನೋಡಬಲ್ಲದು, ಆದ್ದರಿಂದ ಎಂದಿಗೂ ಸೋಲುವುದಿಲ್ಲ. ದೊಡ್ಡ ಹಲಗೆಗಳಲ್ಲಿ ಆಟಗಳು ತುಂಬಾ ಹೆಚ್ಚು, ಆದ್ದರಿಂದ ಕೆಲವು ನಡೆ ಮುಂದೆ ನೋಡಿ ಜಾಣತನದಿಂದ ಅಂದಾಜಿಸುತ್ತದೆ.',
    help_family: 'ಕುಟುಂಬಕ್ಕೆ: ರೈಲಿನಲ್ಲಿ ಅಥವಾ ಕಾಯುವಾಗ ಒಂದೇ ಫೋನ್ ಕೈಯಿಂದ ಕೈಗೆ ಕೊಡಿ. ಚಿಕ್ಕವರನ್ನು ಮೊದಲು ಆಡಲು ಬಿಡಿ, ಸುಲಭ ಮಟ್ಟ ಆರಿಸಿ, ಅಥವಾ 3 ಅಂಕಿಯ ಎತ್ತು ಮತ್ತು ಹಸು ಆಡಿ. ಅಂಕಗಳು ಮತ್ತು ಅರ್ಧ ಆಟಗಳು ಈ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತವೆ.',
